export const FIELDS: string[] = [...new Set(SPECIALITIES.map((s) => s.field))].sort(
  (a, b) => a.localeCompare(b, "ar"),
);

export function getSpeciality(slug: string): Speciality | null {
  return SPECIALITIES.find((s) => s.slug === slug) ?? null;
}

/** بحث بالعربية والفرنسية والأسماء البديلة معاً — التلميذ قد يكتب ESI أو
    «إعلام آلي» أو «انفورماتيك»، وكلّها يجب أن تصل. */
export function searchSpecialities(q: string, field?: string): Speciality[] {
  const t = q.trim().toLowerCase();
  return SPECIALITIES.filter((s) => {
    if (field && s.field !== field) return false;
    if (!t) return true;
    const hay = [s.ar, s.fr ?? "", ...(s.alt ?? []), s.field].join(" ").toLowerCase();
    return hay.includes(t);
  });
}
